   border-radius: 6px;
   color: var(--ink);
   background: var(--surface-soft);
   font-size: 23px;
   cursor: pointer;
 }

 .participant-control button:disabled {
   color: var(--muted);
   cursor: not-allowed;
 }

 .participant-control input {
   width: 72px;
   height: 44px;
   border: 1px solid var(--line);
   border-radius: 6px;
   color: var(--ink);
   background: var(--surface);
