   margin: 0;
   padding-bottom: 18px;
   border-bottom: 1px solid var(--line);
 }

 .summary-grid > div {
   min-width: 0;
 }

 .summary-grid dt {
   margin-bottom: 4px;
   color: var(--muted);
   font-size: 11px;
 }

 .summary-grid dd {
   margin: 0;
   overflow-wrap: anywhere;
   font-size: 14px;
   font-weight: 700;
 }

 .summary-grid .summary-total dd {
   color: var(--green-dark);
   font-size: 19px;
 }

 .reservation-status {
   margin: 16px 0 12px;
   padding: 12px 14px;
   border-radius: 6px;
   font-size: 12px;
 }

 .reservation-status.is-valid {
   color: #205d42;
   background: #e7f4eb;
 }

 .reservation-status.is-invalid {
   color: #75401f;
   background: #fff2df;
 }

 .status-heading {
   margin: 0;
