 }

 .reservation-status ul {
   margin: 7px 0 0;
   padding-left: 18px;
 }

 .reservation-status ul:empty {
   display: none;
 }

 .confirm-button {
   min-height: 44px;
   padding: 0 18px;
   border: 0;
   border-radius: 6px;
   color: #fff;
   background: var(--green-dark);
   font: 700 13px/1 "Trebuchet MS", "Segoe UI", sans-serif;
   cursor: pointer;
 }

 .confirm-button:disabled {
   color: #f4f7f5;
   background: #52645e;
   cursor: not-allowed;
 }

 .phase-note {
   color: var(--green);
   font-weight: 700;
 }

 .visually-hidden {
   position: absolute;
   width: 1px;
   height: 1px;
   padding: 0;
   margin: -1px;
   overflow: hidden;
   clip: rect(0, 0, 0, 0);
