     private static void deleteTree(Path path) throws IOException {
         if (!Files.exists(path)) {
             return;
         }
         try (var entries = Files.walk(path)) {
             for (Path entry : entries.sorted(java.util.Comparator.reverseOrder()).toList()) {
                 Files.delete(entry);
             }
         }
     }

